    uint64_t C = origin.GetDim(1);
    uint64_t D = origin.GetDim(2);
    uint64_t H = origin.GetDim(3);
    uint64_t W = origin.GetDim(4);

    uint64_t totalRows = N * D * H * W;
    tiling.set_totalRows(static_cast<uint32_t>(totalRows));
    tiling.set_width(static_cast<uint32_t>(C));

    // 设置 block 数量（可按行并行）
